#revisawiki-ptwiki{box-sizing:border-box;border:1px solid var(--border-color-subtle,#c8ccd1);border-radius:6px;padding:12px 14px;margin:10px 0;background:var(--background-color-base,#fff);color:var(--color-base,#202122);font:14px/1.45 sans-serif;overflow-wrap:anywhere}
#revisawiki-ptwiki *{box-sizing:border-box}
#revisawiki-ptwiki [hidden]{display:none!important}
#revisawiki-ptwiki .ajg-heading{display:flex;align-items:baseline;flex-wrap:wrap;gap:8px;margin-bottom:4px}
#revisawiki-ptwiki .ajg-heading strong{font-size:16px}
#revisawiki-ptwiki .ajg-version{font-size:12px;color:var(--color-subtle,#54595d)}
#revisawiki-ptwiki .ajg-intro{margin:0 0 10px;color:var(--color-subtle,#54595d);font-size:13px;line-height:1.5}
#revisawiki-ptwiki .ajg-actions{display:flex;flex-wrap:wrap;align-items:center;gap:6px}
#revisawiki-ptwiki button{min-height:32px;max-width:100%;white-space:normal;border-radius:3px;font-size:13px}
#revisawiki-ptwiki .ajg-status{margin-top:10px;padding:6px 8px;background:var(--background-color-neutral-subtle,#f8f9fa);border-inline-start:3px solid var(--border-color-subtle,#c8ccd1);font-size:13px}
#revisawiki-ptwiki[aria-busy=true] .ajg-status{border-inline-start-color:var(--color-progressive,#36c)}
#revisawiki-ptwiki summary{cursor:pointer;padding:3px 0;font-weight:600}
#revisawiki-ptwiki summary:focus-visible,#revisawiki-ptwiki button:focus-visible,#revisawiki-ptwiki select:focus-visible{outline:2px solid var(--color-progressive,#36c);outline-offset:2px}
#revisawiki-ptwiki .ajg-tools{display:flex;flex-wrap:wrap;gap:6px 20px;margin-top:7px;color:var(--color-subtle,#54595d)}
#revisawiki-ptwiki .ajg-tools>details{min-width:0;flex:1 1 250px;margin:0}
#revisawiki-ptwiki .ajg-tools>details[open]{flex-basis:100%}
#revisawiki-ptwiki .ajg-tools summary{font-size:13px}
#revisawiki-ptwiki .ajg-options{display:grid;grid-template-columns:repeat(auto-fit,minmax(225px,1fr));gap:5px 16px;margin:8px 0}
#revisawiki-ptwiki .ajg-options label{min-height:24px;display:flex!important;align-items:flex-start;gap:5px;margin:0!important;color:var(--color-base,#202122);font-size:13px}
#revisawiki-ptwiki .ajg-options input{flex:none;margin-top:3px}
#revisawiki-ptwiki select{max-width:100%;margin-top:7px;padding:4px;background:var(--background-color-base,#fff);color:var(--color-base,#202122);border:1px solid var(--border-color-base,#a2a9b1);border-radius:3px}
#revisawiki-ptwiki .ajg-report,#revisawiki-ptwiki .ajg-diff{max-height:420px;overflow:auto;scrollbar-gutter:stable;margin-top:8px}
#revisawiki-ptwiki .ajg-diff:empty{display:none}
#revisawiki-ptwiki .ajg-comparison-controls{position:sticky;top:0;z-index:1;background:var(--background-color-base,#fff);padding:6px 0;border-bottom:1px solid var(--border-color-subtle,#c8ccd1);margin-bottom:6px}
#revisawiki-ptwiki .ajg-suggestions>details,#revisawiki-ptwiki .ajg-issue-group{margin-top:8px;padding:7px 9px;border:1px solid var(--border-color-subtle,#c8ccd1);border-radius:4px}
#revisawiki-ptwiki .ajg-issues ul{padding-inline-start:20px}
#revisawiki-ptwiki .ajg-issue{padding:4px 0}
#revisawiki-ptwiki .ajg-issue button{min-height:27px;font-size:12px;padding:3px 7px;margin-top:3px}
#revisawiki-ptwiki .ajg-individual-checks{margin-top:5px}
#revisawiki-ptwiki .ajg-style-choices details{margin-top:8px}
#revisawiki-ptwiki pre{color:var(--color-base,#202122);background:var(--background-color-neutral-subtle,#f8f9fa);border:1px solid var(--border-color-subtle,#c8ccd1);border-radius:3px;padding:8px;line-height:1.5;font-size:12px}
#revisawiki-ptwiki .ajg-stop,#revisawiki-ptwiki .ajg-cancel{color:var(--color-destructive,#b32424)}
@media(max-width:600px){#revisawiki-ptwiki{padding:10px}#revisawiki-ptwiki .ajg-options{grid-template-columns:1fr}#revisawiki-ptwiki .ajg-tools>details{flex-basis:100%}}

#revisawiki-ptwiki .ajg-top{display:flex;align-items:center;flex-wrap:wrap;gap:8px 20px}
#revisawiki-ptwiki .ajg-top .ajg-heading{margin:0}
#revisawiki-ptwiki .ajg-intro{margin:4px 0 0;font-size:13px}
#revisawiki-ptwiki .ajg-actions .ajg-run{font-weight:600}
#revisawiki-ptwiki .ajg-run{background:var(--background-color-progressive,#36c);border-color:var(--border-color-progressive,#36c);color:var(--color-inverted,#fff)}
#revisawiki-ptwiki .ajg-run:hover{background:var(--background-color-progressive--hover,#3056a9)}
#revisawiki-ptwiki .ajg-result{display:flex;align-items:center;flex-wrap:wrap;gap:8px 20px;padding:10px 0;margin-top:10px;border-top:1px solid var(--border-color-subtle,#c8ccd1)}
#revisawiki-ptwiki .ajg-result-copy{flex:1;min-width:160px}
#revisawiki-ptwiki .ajg-result-title{font-size:14px}
#revisawiki-ptwiki .ajg-result-count{display:block;color:var(--color-subtle,#54595d);font-size:13px}
#revisawiki-ptwiki .ajg-result-actions{display:flex;flex-wrap:wrap;gap:6px}
#revisawiki-ptwiki .ajg-report{max-height:none;overflow:visible;margin-top:0}
#revisawiki-ptwiki .ajg-diff{max-height:420px;overflow:auto;margin:0}
#revisawiki-ptwiki .ajg-comparison{border-top:1px solid var(--border-color-subtle,#c8ccd1);padding-top:5px}
#revisawiki-ptwiki .ajg-change{border-top:1px solid var(--border-color-subtle,#c8ccd1);padding:8px 0}
#revisawiki-ptwiki .ajg-change-explanation{margin:0 0 6px;font-weight:600;font-size:13px}
#revisawiki-ptwiki .ajg-context{white-space:pre-wrap;overflow-wrap:anywhere;word-break:break-word;font-size:13px;line-height:1.55;margin:4px 0 8px;max-height:220px;overflow:auto}
#revisawiki-ptwiki .ajg-context mark{color:inherit}
#revisawiki-ptwiki .ajg-before mark{background:var(--background-color-error-subtle,rgba(221,51,51,.18))}
#revisawiki-ptwiki .ajg-after mark{background:var(--background-color-success-subtle,rgba(0,175,80,.18))}
#revisawiki-ptwiki .ajg-selection-help{display:none}
#revisawiki-ptwiki .ajg-selecting .ajg-selection-help{display:block}
#revisawiki-ptwiki .ajg-change label{font-size:13px;margin-bottom:6px}
#revisawiki-ptwiki .ajg-change input{width:auto}
#revisawiki-ptwiki .ajg-choice-item{display:flex;align-items:flex-start;flex-wrap:wrap;gap:4px 8px;margin:5px 0;font-size:13px}
#revisawiki-ptwiki .ajg-choice-item input{width:auto;flex:none;margin:3px 0 0}
#revisawiki-ptwiki .ajg-choice-item code{overflow-wrap:anywhere;white-space:pre-wrap;font-size:12px}
#revisawiki-ptwiki .ajg-comparison-controls{position:static;padding:6px 0}
#revisawiki-ptwiki .ajg-comparison-controls p{font-size:13px;margin:6px 0}
#revisawiki-ptwiki .ajg-review-area{margin:8px 0;border-top:1px solid var(--border-color-subtle,#c8ccd1);padding-top:5px}
#revisawiki-ptwiki .ajg-issue-group{border:0;border-radius:0;padding:2px 0;margin:4px 0}
#revisawiki-ptwiki .ajg-review-history{margin-top:8px;color:var(--color-subtle,#54595d)}
#revisawiki-ptwiki .ajg-suggestions>details{border:0;border-top:1px solid var(--border-color-subtle,#c8ccd1);border-radius:0;padding:6px 0}
#revisawiki-ptwiki .ajg-automatic:empty{display:none}
#revisawiki-ptwiki .ajg-automatic p{font-size:13px;margin:6px 0}
#revisawiki-ptwiki .ajg-tools{border-top:1px solid var(--border-color-subtle,#c8ccd1);padding-top:5px;margin-top:8px;gap:6px 20px}
#revisawiki-ptwiki .ajg-tools>details{flex:0 1 auto}
#revisawiki-ptwiki .ajg-online{border:0;margin:3px 0;padding:0}
#revisawiki-ptwiki .ajg-tools .ajg-settings,#revisawiki-ptwiki .ajg-tools .ajg-spelling-settings,#revisawiki-ptwiki .ajg-tools .ajg-diagnostics{margin-top:8px}
#revisawiki-ptwiki .ajg-online-controls:empty{display:none}
@media(max-width:600px){#revisawiki-ptwiki .ajg-top{gap:6px}#revisawiki-ptwiki .ajg-result{align-items:flex-start}#revisawiki-ptwiki .ajg-result-actions{width:100%}#revisawiki-ptwiki .ajg-diff{max-height:420px}}
